style.css:
@-moz-document domain("google.com") {
/* ==========================
       VARIÁVEIS DO TEMA — ROSA
       ========================== */
    :root {
        -rosa-principal: #d64583;     /* Rosa choque */
        -rosa-escuro:    #d64583;     /* Rosa profundo */
        -rosa-claro:     #ffd5e7;     /* Rosa pastel */
        -texto-escuro:   #2a2a2a;
        -texto-claro:    #ffd5e7;
        -cinza:          #ffd5e7;
    }

    /* ==========================
       FUNDO GERAL
       ========================== */
    body {
        background: var(--rosa-claro) !important;
        color: var(--texto-escuro) !important;
    }

    /* ==========================
       LOGO DO GOOGLE (remove cor original)
       ========================== */
    img[src*="googlelogo"] {
        filter: hue-rotate(310deg) saturate(2.5);  
        /* isso “puxa” o logo para tons rosados */
    }

    /* ==========================
       BARRA DE PESQUISA
       ========================== */
    input[type="text"] {
        background: #ffffff !important;
        border: 2px solid var(--rosa-principal) !important;
        border-radius: 30px !important;
        padding: 10px 20px !important;
        color: var(--texto-escuro) !important;
        transition: 0.2s ease-in-out;
    }

    input[type="text"]:focus {
        border-color: var(--rosa-escuro) !important;
        box-shadow: 0 0 8px var(--rosa-principal) !important;
    }

    /* ==========================
       BOTÕES DE PESQUISA
       ========================== */
    input[type="submit"],
    button {
        background: var(--rosa-principal) !important;
        color: var(--texto-claro) !important;
        border: none !important;
        padding: 8px 20px !important;
        border-radius: 20px !important;
        font-weight: bold !important;
        transition: 0.2s ease-in-out;
    }

    input[type="submit"]:hover,
    button:hover {
        background: var(--rosa-escuro) !important;
    }

    /* ==========================
       RODAPÉ
       ========================== */
    footer, #fbar {
        background: var(--rosa-claro) !important;
        border-top: 2px solid var(--rosa-principal) !important;
        color: var(--texto-escuro) !important;
    }
}
